package com.quincaisoft.purchasing.web;
import com.quincaisoft.purchasing.api.PurchasingService;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;
@RestController @RequestMapping("/api/v1/purchases") public class PurchasingController {
 private final PurchasingService service;public PurchasingController(PurchasingService service){this.service=service;}
 @GetMapping @PreAuthorize("hasAnyAuthority('purchasing:read','SCOPE_purchasing:read')") public List<PurchasingService.Purchase> list(){return service.list();}
 @GetMapping("/{id}") @PreAuthorize("hasAnyAuthority('purchasing:read','SCOPE_purchasing:read')") public PurchasingService.Purchase get(@PathVariable UUID id){return service.get(id);}
 @PostMapping @PreAuthorize("hasAnyAuthority('purchasing:write','SCOPE_purchasing:write')") public PurchasingService.Purchase draft(@RequestHeader("Idempotency-Key") UUID key,@RequestHeader("X-Request-ID") UUID requestId,@RequestBody PurchasingService.Draft body){match(key,body.operationId());return service.draft(body);}
 @PostMapping("/{id}/submit") @PreAuthorize("hasAnyAuthority('purchasing:write','SCOPE_purchasing:write')") public PurchasingService.Purchase submit(@PathVariable UUID id,@RequestHeader("Idempotency-Key") UUID key,@RequestHeader("X-Request-ID") UUID requestId,@RequestBody PurchasingService.Decision body){match(key,body.operationId());return service.submit(id,body);}
 @PostMapping("/{id}/approve") @PreAuthorize("hasAnyAuthority('purchasing:approve','SCOPE_purchasing:approve')") public PurchasingService.Purchase approve(@PathVariable UUID id,@RequestHeader("Idempotency-Key") UUID key,@RequestHeader("X-Request-ID") UUID requestId,@RequestBody PurchasingService.Decision body){match(key,body.operationId());return service.approve(id,body);}
 @PostMapping("/{id}/receipts") @PreAuthorize("hasAnyAuthority('purchasing:receive','SCOPE_purchasing:receive')") public PurchasingService.Receipt receive(@PathVariable UUID id,@RequestHeader("Idempotency-Key") UUID key,@RequestHeader("X-Request-ID") UUID requestId,@RequestBody PurchasingService.Receive body){match(key,body.operationId());return service.receive(id,body);}
 @GetMapping("/{id}/receipts") @PreAuthorize("hasAnyAuthority('purchasing:read','SCOPE_purchasing:read')") public List<PurchasingService.Receipt> receipts(@PathVariable UUID id){return service.receipts(id);}
 @PostMapping("/receipts/{id}/invoice") @PreAuthorize("hasAnyAuthority('purchasing:invoice','SCOPE_purchasing:invoice')") public PurchasingService.Invoice invoice(@PathVariable UUID id,@RequestHeader("Idempotency-Key") UUID key,@RequestHeader("X-Request-ID") UUID requestId,@RequestBody PurchasingService.InvoiceRequest body){match(key,body.operationId());return service.invoice(id,body);}
 @GetMapping("/invoices") @PreAuthorize("hasAnyAuthority('purchasing:read','SCOPE_purchasing:read')") public List<PurchasingService.Invoice> invoices(){return service.invoices();}
 @PostMapping("/receipts/{id}/returns") @PreAuthorize("hasAnyAuthority('purchasing:return','SCOPE_purchasing:return')") public PurchasingService.SupplierReturn returnToSupplier(@PathVariable UUID id,@RequestHeader("Idempotency-Key") UUID key,@RequestHeader("X-Request-ID") UUID requestId,@RequestBody PurchasingService.ReturnRequest body){match(key,body.operationId());return service.returnToSupplier(id,body);}
 @GetMapping("/receipts/{id}/returns") @PreAuthorize("hasAnyAuthority('purchasing:read','SCOPE_purchasing:read')") public List<PurchasingService.SupplierReturn> supplierReturns(@PathVariable UUID id){return service.supplierReturns(id);}
 private void match(UUID key,UUID operation){if(!key.equals(operation))throw new IllegalArgumentException("Idempotency-Key must match operationId");}
}